<?php
declare(strict_types=1);require_once __DIR__.'/config/finance_step16.php';$error=null;$rows=[];$months=max(1,min(36,(int)($_GET['months']??12)));
try{$pdo=business_db();finance_step16_ensure($pdo);finance_step16_sync_all($pdo);$ctx=finance_step16_context($pdo);$orgId=(int)$ctx['organization_id'];$start=(new DateTimeImmutable('first day of this month'))->modify('-'.($months-1).' months')->format('Y-m-01');$stmt=$pdo->prepare("SELECT DATE_FORMAT(j.journal_date,'%Y-%m') month_key,SUM(CASE WHEN a.account_class='income' THEN l.credit_amount-l.debit_amount ELSE 0 END) income_amount,SUM(CASE WHEN a.account_class='expense' THEN l.debit_amount-l.credit_amount ELSE 0 END) expense_amount,SUM(CASE WHEN l.cash_account_id IS NOT NULL AND l.debit_amount>0 THEN l.debit_amount ELSE 0 END) cash_in,SUM(CASE WHEN l.cash_account_id IS NOT NULL AND l.credit_amount>0 THEN l.credit_amount ELSE 0 END) cash_out FROM finance_journal_lines l JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id JOIN finance_ledger_accounts a ON a.id=l.ledger_account_id AND a.organization_id=l.organization_id WHERE l.organization_id=? AND j.journal_date>=? GROUP BY DATE_FORMAT(j.journal_date,'%Y-%m') ORDER BY month_key DESC");$stmt->execute([$orgId,$start]);$rows=$stmt->fetchAll();foreach($rows as &$r){$r['profit']=round((float)$r['income_amount']-(float)$r['expense_amount'],2);$r['cash_net']=round((float)$r['cash_in']-(float)$r['cash_out'],2);}unset($r);}catch(Throwable $e){$error=$e->getMessage();}
function fm_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function fm_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Monthly Finance Summary - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="finance_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 16 • Monthly Financial Summary</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_profit_loss.php">P&amp;L</a><a class="os-btn" href="finance_cash_flow.php">Cash Flow</a><a class="os-btn primary" href="finance_center.php">Finance Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Statements</div><nav class="os-nav"><a href="finance_center.php"><i class="dot"></i>Finance Center</a><a href="finance_profit_loss.php"><i class="dot"></i>P&amp;L</a><a href="finance_cash_flow.php"><i class="dot"></i>Cash Flow</a><a class="active" href="finance_monthly.php"><i class="dot"></i>Monthly Summary</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 16J • MONTHLY FINANCIAL VIEW</div><h1>Compare accounting profit with actual cash movement month by month.</h1><p>Profit and cash are intentionally separate: invoices/bills affect accrual accounting, while cash flow changes only when a liquid account moves.</p></section><section class="os-card" style="margin-top:14px"><form method="get" class="pp-form"><label>Months<select name="months"><?php foreach([6,12,18,24,36] as $n):?><option value="<?= $n ?>" <?= $months===$n?'selected':'' ?>>Last <?= $n ?> months</option><?php endforeach;?></select></label><button>Apply</button></form></section><?php if($error):?><div class="pp-alert bad"><strong>Monthly diagnostic:</strong> <?= fm_h($error) ?></div><?php else:?><section class="os-card" style="margin-top:14px"><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Month</th><th>Income</th><th>Expense</th><th>Profit / Loss</th><th>Cash In</th><th>Cash Out</th><th>Net Cash</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?= fm_h($r['month_key']) ?></b></td><td><?= fm_m($r['income_amount']) ?></td><td><?= fm_m($r['expense_amount']) ?></td><td><b><?= fm_m($r['profit']) ?></b></td><td><?= fm_m($r['cash_in']) ?></td><td><?= fm_m($r['cash_out']) ?></td><td><b><?= fm_m($r['cash_net']) ?></b></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7">No accounting activity in this range.</td></tr><?php endif;?></tbody></table></div></section><div class="os-footer-note"><strong>Interpretation:</strong> a profitable month can still have negative cash movement if receivables are unpaid or supplier payments are made in a different period.</div><?php endif;?></main></div></body></html>